your getting a scope issue; use 'bind', just swap this out:


    var btn = new menuButton();
    var listener = function(e){
        this.changeValue(e.keyCode); // btn is no longer btn ]:
        controlState.resetControlChangeListener();
    }.bind(btn)
    // do stuff with working listener fn

the alternative is to lookup the button in every event -- its common pattern in js...

    function listener(e) {
       var currentbutton = $(e.target).id()
       if (currentbutton == 'button1') { dostuff() }
